// The welded header table: libc headers this compiler carries already
// preprocessed.
//
// Generated by tools/scripts/gen_libc_headers.py from the headers themselves;
// do not edit by hand. What lives here is data only. The code that reads it is
// preprocess.c.
//
// One entry per header holds only that header's own tokens, not the tokens of
// the headers it includes: those are entries of their own, and they are spliced
// first, in the order this header includes them. Storing the whole expansion in
// every entry would put the same declarations in the program once per header
// that reaches them, which the file path avoids through include guards and a
// welded entry cannot, having no directives left.

#ifndef WNJR_WELD_H
#define WNJR_WELD_H

typedef struct {
  const char *name;     // the name as written in #include <name>
  const char *text;     // this header's own tokens, already preprocessed
  const char *macros;   // the "#define" lines it leaves behind, or NULL
  const char **deps;    // the welded headers it includes, in order
  int n_deps;
} WeldHeader;

extern const WeldHeader weld_headers[];
extern const int weld_headers_len;

#endif
